const words={
  en:{home:"Overview",services:"Service directory",assistant:"Civic AI assistant",report:"New request",requests:"My requests",track:"Track a request",staff:"Staff workspace",search:"Search services…",location:"Hyderabad · Demo city",workspace:"CITIZEN WORKSPACE",intro:"Let’s make things better.",sub:"Your local services. One simple place.",new:"Raise a request",heroLabel:"YOUR CITY. YOUR VOICE.",heroTitle:"A better city starts\nwith a conversation.",heroSub:"Find the right service. Raise an issue.\nStay in the loop, every step of the way.",ask:"Ask Civic AI",explore:"Explore services",popular:"How can we help?",viewAll:"View all services",recent:"Recent requests",seeAll:"See all requests",total:"Total requests",active:"In progress",resolved:"Resolved",sample:"Sample",demo:"DEMO WORKSPACE",askPlaceholder:"Ask about a service or describe your issue…",send:"Send message",subject:"Subject",description:"Describe the issue",category:"Service category",area:"Area or nearby landmark",submit:"Submit demo request",back:"Back",help:"Need a little guidance?",helpText:"Civic AI can help you find the right service and understand what to include.",trackCode:"Tracking code",reference:"Reference number",find:"Find my request",nothing:"No requests match your filters.",loading:"Loading your workspace…"},
  te:{home:"అవలోకనం",services:"సేవల జాబితా",assistant:"సివిక్ AI సహాయకుడు",report:"కొత్త అభ్యర్థన",requests:"నా అభ్యర్థనలు",track:"అభ్యర్థన స్థితి",staff:"సిబ్బంది విభాగం",search:"సేవలను వెతకండి…",location:"హైదరాబాద్ · నమూనా నగరం",workspace:"పౌరుల విభాగం",intro:"మన నగరాన్ని మెరుగుపరుద్దాం.",sub:"స్థానిక సేవలన్నీ ఒకే చోట.",new:"అభ్యర్థన చేయండి",heroLabel:"మీ నగరం. మీ స్వరం.",heroTitle:"మెరుగైన నగరం\nమీ మాటతో మొదలవుతుంది.",heroSub:"సరైన సేవను కనుగొనండి. సమస్యను తెలియజేయండి.\nప్రతి దశలో స్థితిని తెలుసుకోండి.",ask:"సివిక్ AI ని అడగండి",explore:"సేవలను చూడండి",popular:"మేము ఎలా సహాయపడగలం?",viewAll:"అన్ని సేవలు",recent:"ఇటీవలి అభ్యర్థనలు",seeAll:"అన్ని అభ్యర్థనలు",total:"మొత్తం అభ్యర్థనలు",active:"పురోగతిలో",resolved:"పరిష్కరించబడినవి",sample:"నమూనా",demo:"నమూనా విభాగం",askPlaceholder:"సేవ గురించి అడగండి లేదా సమస్యను వివరించండి…",send:"సందేశం పంపండి",subject:"విషయం",description:"సమస్యను వివరించండి",category:"సేవ విభాగం",area:"ప్రాంతం లేదా సమీప గుర్తింపు స్థలం",submit:"నమూనా అభ్యర్థన సమర్పించండి",back:"వెనుకకు",help:"మార్గదర్శనం కావాలా?",helpText:"సరైన సేవను కనుగొనడానికి సివిక్ AI సహాయపడుతుంది.",trackCode:"ట్రాకింగ్ కోడ్",reference:"రిఫరెన్స్ నంబర్",find:"నా అభ్యర్థనను కనుగొనండి",nothing:"ఈ ఫిల్టర్‌లకు అభ్యర్థనలు లేవు.",loading:"మీ విభాగం లోడ్ అవుతోంది…"},
  hi:{home:"अवलोकन",services:"सेवा सूची",assistant:"सिविक AI सहायक",report:"नया अनुरोध",requests:"मेरे अनुरोध",track:"अनुरोध की स्थिति",staff:"कर्मचारी कार्यक्षेत्र",search:"सेवाएं खोजें…",location:"हैदराबाद · नमूना शहर",workspace:"नागरिक कार्यक्षेत्र",intro:"आइए शहर को बेहतर बनाएं.",sub:"आपकी स्थानीय सेवाएं. एक आसान जगह.",new:"अनुरोध दर्ज करें",heroLabel:"आपका शहर. आपकी आवाज़.",heroTitle:"बेहतर शहर की शुरुआत\nएक बातचीत से होती है.",heroSub:"सही सेवा खोजें. समस्या दर्ज करें.\nहर कदम पर स्थिति जानें.",ask:"सिविक AI से पूछें",explore:"सेवाएं देखें",popular:"हम कैसे मदद कर सकते हैं?",viewAll:"सभी सेवाएं",recent:"हाल के अनुरोध",seeAll:"सभी अनुरोध",total:"कुल अनुरोध",active:"कार्य प्रगति पर",resolved:"हल किए गए",sample:"नमूना",demo:"नमूना कार्यक्षेत्र",askPlaceholder:"सेवा के बारे में पूछें या अपनी समस्या बताएं…",send:"संदेश भेजें",subject:"विषय",description:"समस्या का विवरण",category:"सेवा श्रेणी",area:"क्षेत्र या पास का पहचान स्थल",submit:"नमूना अनुरोध जमा करें",back:"वापस",help:"मार्गदर्शन चाहिए?",helpText:"सिविक AI सही सेवा खोजने और अनुरोध लिखने में मदद कर सकता है.",trackCode:"ट्रैकिंग कोड",reference:"संदर्भ संख्या",find:"मेरा अनुरोध खोजें",nothing:"इन फ़िल्टर के लिए कोई अनुरोध नहीं मिला.",loading:"आपका कार्यक्षेत्र लोड हो रहा है…"}
};
type Labels=typeof words.en;
const routeFor:Record<View,string>={home:"/",services:"/services",assistant:"/assistant",report:"/report",requests:"/requests",track:"/track",staff:"/staff"};
async function api<T=Record<string,unknown>>(url:string,options?:RequestInit):Promise<T>{
  const response=await fetch(url,{signal:AbortSignal.timeout(25000),...options,headers:{...(options?.body instanceof FormData?{}:{"Content-Type":"application/json"}),...options?.headers}});
  const data=await response.json();if(!response.ok)throw new Error(data.error||"Something went wrong. Please try again.");return data;
}
const shortDate=(v:string)=>new Date(v).toLocaleDateString("en-IN",{day:"numeric",month:"short"});
const longDate=(v:string)=>new Date(v).toLocaleString("en-IN",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",timeZone:"Asia/Kolkata"});
function Icon({name,size=22}:{name:string;size?:number}){const Component=icons[name]||Building2;return <Component size={size} strokeWidth={1.7}/>;}
function StatusBadge({status}:{status:string}){return <span className={`status-badge status-${status.toLowerCase().replaceAll(" ","-")}`}><span/>{status}</span>;}
function Spinner(){return <Loader2 size={18} className="spin" aria-hidden="true"/>;}
function ErrorNotice({children}:{children:ReactNode}){return <div className="error-notice" role="alert"><CircleHelp size={18}/><span>{children}</span></div>;}
function Logo(){return <div className="brand"><span className="brand-mark"><Building2 size={23} strokeWidth={1.8}/></span><span>civic<span className="brand-light">bridge</span><span className="brand-dot">.</span></span></div>;}

export default function CivicApp({initialView="home",initialServiceId=null}:{initialView?:View;initialServiceId?:string|null}){
  const [view,setView]=useState<View>(initialView),[language,setLanguage]=useState<Language>("en");
  const [selectedService,setSelectedService]=useState<string|null>(initialServiceId),[directorySearch,setDirectorySearch]=useState("");
  const [requests,setRequests]=useState<Grievance[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");
  const [staff,setStaff]=useState(false),[mobileNav,setMobileNav]=useState(false),[detail,setDetail]=useState<Grievance|null>(null);
  const [reportCategory,setReportCategory]=useState(""),[messages,setMessages]=useState<Message[]>([]),[chatBusy,setChatBusy]=useState(false);
  const [chatError,setChatError]=useState("");const [queueVersion,setQueueVersion]=useState(0);const t=words[language];
  async function refresh(){const r=await api<{requests:Grievance[]}>("/api/grievances");setRequests(r.requests);}
  async function initialize(){setLoading(true);setError("");try{const session=await api<{staff:boolean}>("/api/session");setStaff(session.staff);await refresh();}catch(e){setError((e as Error).message);}finally{setLoading(false);}}
  useEffect(()=>{void initialize();const saved=localStorage.getItem("civic-language");if(saved&&["en","te","hi"].includes(saved))setLanguage(saved as Language);},[]); // A browser-scoped demo identity is created by the server.
  useEffect(()=>{document.documentElement.lang=language;localStorage.setItem("civic-language",language);},[language]);
  useEffect(()=>{const pop=()=>{const parts=window.location.pathname.split("/").filter(Boolean);setView((Object.keys(routeFor) as View[]).find(k=>routeFor[k]===`/${parts[0]||""}`)||"home");setSelectedService(parts[0]==="services"?parts[1]||null:null);setDetail(null);};window.addEventListener("popstate",pop);return()=>window.removeEventListener("popstate",pop);},[]);
  function navigate(next:View,serviceId:string|null=null){setView(next);setSelectedService(serviceId);setMobileNav(false);setError("");window.history.pushState({},"",serviceId?`/services/${serviceId}`:routeFor[next]);window.scrollTo({top:0,behavior:"instant"});}
  function report(category=""){setReportCategory(category);navigate("report");}
  async function ask(question:string){
    if(chatBusy||!question.trim()||loading)return;setChatError("");navigate("assistant");setChatBusy(true);
    const contextId=[...messages].reverse().find(m=>m.sources?.length)?.sources?.[0]?.id;
    setMessages(m=>[...m,{role:"user",text:question.trim()}]);
    try{const r=await api<{answer:string;sources:Source[];mode:string;category:string|null}>("/api/chat",{method:"POST",body:JSON.stringify({question:question.trim(),language,contextId})});setMessages(m=>[...m,{role:"assistant",text:r.answer,sources:r.sources,mode:r.mode,category:r.category,question}]);}
    catch(e){setChatError((e as Error).message);}finally{setChatBusy(false);}
  }
  const nav=[{id:"home" as View,icon:LayoutDashboard},{id:"services" as View,icon:Building2},{id:"assistant" as View,icon:Sparkles},{id:"requests" as View,icon:Inbox},{id:"track" as View,icon:Search}];
  return <div className="app-shell">
    {mobileNav&&<button className="nav-scrim" aria-label="Close navigation" onClick={()=>setMobileNav(false)}/>}
    <aside className={`sidebar ${mobileNav?"sidebar-open":""}`}>
      <a href="/" className="brand-link" onClick={e=>{e.preventDefault();navigate("home");}} aria-label="CivicBridge home"><Logo/></a>
      <div className="workspace-tag"><span className="live-dot"/>{t.demo}</div>
      <p className="nav-caption">WORKSPACE</p>
      <nav aria-label="Main navigation">{nav.map(n=><button key={n.id} className={`nav-item ${view===n.id?"active":""}`} onClick={()=>navigate(n.id)} aria-current={view===n.id?"page":undefined}><n.icon size={19}/><span>{t[n.id as keyof Labels]}</span>{n.id==="assistant"&&<span className="nav-ai">AI</span>}{n.id==="requests"&&<span className="nav-count">{requests.length}</span>}</button>)}</nav>
      <button className="sidebar-report" onClick={()=>report()}><Plus size={18}/>{t.new}</button>
      <div className="sidebar-bottom"><div className="sidebar-note"><div className="small-orbit"><Leaf size={20}/></div><strong>Small actions.<br/>Better neighbourhoods.</strong><p>Every voice helps build a city that works for everyone.</p></div><button className={`nav-item staff-nav ${view==="staff"?"active":""}`} onClick={()=>navigate("staff")}><ShieldCheck size={18}/><span>{t.staff}</span><ArrowUpRight size={15}/></button><div className="prototype-id">STUDENT PROTOTYPE <span>HACK-P438</span></div></div>
    </aside>
    <div className="main-shell">
      <header className="topbar"><div className="topbar-left"><button className="icon-button menu-button" onClick={()=>setMobileNav(true)} aria-label="Open navigation"><Menu size={23}/></button><span className="breadcrumb">Workspace <ChevronRight size={14}/> <strong>{t[view as keyof Labels]}</strong></span></div><div className="topbar-right"><form className="header-search" onSubmit={e=>{e.preventDefault();navigate("services");}}><Search size={16}/><input aria-label="Search service directory" placeholder={t.search} value={directorySearch} onChange={e=>setDirectorySearch(e.target.value)}/><kbd>↵</kbd></form><label className="language-select"><Globe2 size={16}/><select aria-label="Choose language" value={language} onChange={e=>setLanguage(e.target.value as Language)}><option value="en">English</option><option value="te">తెలుగు</option><option value="hi">हिन्दी</option></select><ChevronDown size={12}/></label><span className="header-divider"/><button className="icon-button notification-button" aria-label="View recent requests" onClick={()=>navigate("requests")}><Bell size={19}/>{requests.some(r=>r.status!=="Resolved")&&<span/>}</button><div className="avatar" title="Demo citizen">D</div></div></header>
      <main className={`main-content ${view==="assistant"?"chat-main":""}`} id="main-content">
        {error&&<div className="global-error"><ErrorNotice>{error}</ErrorNotice><button className="text-button" onClick={()=>void initialize()}>Retry connection</button></div>}
        {view==="home"&&<Overview t={t} language={language} requests={requests} loading={loading} onView={navigate} onReport={report} onDetail={setDetail} onAsk={ask}/>}
        {view==="services"&&<Directory t={t} language={language} search={directorySearch} setSearch={setDirectorySearch} selectedId={selectedService} onSelect={id=>navigate("services",id)} onReport={report} onAsk={q=>void ask(q)}/>}
        {view==="assistant"&&<Assistant t={t} language={language} messages={messages} busy={chatBusy||loading} error={chatError} onAsk={ask} onReport={report} onSource={id=>navigate("services",id)} onFeedback={async(index,helpful)=>{try{await api("/api/feedback",{method:"POST",body:JSON.stringify({question:messages[index].question,helpful})});setMessages(m=>m.map((x,i)=>i===index?{...x,feedback:helpful}:x));}catch(e){setChatError((e as Error).message);}}}/>}
        {view==="report"&&<ReportForm key={reportCategory} t={t} category={reportCategory} ready={!loading&&!error} onDone={async()=>refresh()} onDetail={setDetail} onNavigate={navigate}/>}
        {view==="requests"&&<Requests t={t} requests={requests} loading={loading} onDetail={setDetail} onReport={()=>report()} onRefresh={refresh}/>}
        {view==="track"&&<Track t={t} onDetail={setDetail}/>}
        {view==="staff"&&<Staff t={t} staff={staff} version={queueVersion} onLogin={()=>setStaff(true)} onLogout={()=>setStaff(false)} onDetail={setDetail}/>}
        <footer className="page-footer"><span><span className="footer-dot"/>CivicBridge · Student hackathon prototype</span><span>Sample guidance. Requests are not sent to government departments.</span></footer>
      </main>
    </div>
    {detail&&<RequestDialog request={detail} staff={staff&&view==="staff"} onClose={()=>setDetail(null)} onUpdated={async()=>{await refresh();setQueueVersion(v=>v+1);}}/>}
  </div>;
}

function CityIllustration(){return <svg className="city-illustration" viewBox="0 0 360 240" fill="none" aria-hidden="true"><circle cx="262" cy="62" r="38" fill="#DACD75"/><path d="M8 206L170 124L350 211L192 290Z" fill="#C8D3B8"/><path d="M18 207L180 126M62 228L225 148M111 251L273 170M160 275L322 192" stroke="#AFBE9C" strokeWidth="1"/><path d="M86 140L151 107L213 138L148 172Z" fill="#657B61"/><path d="M86 140V196L148 228V172Z" fill="#7F9476"/><path d="M148 172V228L213 194V138Z" fill="#A5B397"/><path d="M97 147V188L139 210V169Z" fill="#D9E3CD"/><path d="M156 177L204 152V184L156 208Z" fill="#3F5A4B"/><path d="M103 157L133 173M103 169L133 185M112 153V193M124 159V200M170 170V199M188 160V189" stroke="#77916E" strokeWidth="3"/><path d="M174 83L218 60L264 83L219 108Z" fill="#CFBD9D"/><path d="M174 83V164L219 188V108Z" fill="#C1AD8C"/><path d="M219 108V188L264 164V83Z" fill="#E4D7BD"/><path d="M185 98V111L196 117V104ZM204 108V121L213 126V113ZM185 123V136L196 142V129ZM204 133V146L213 151V138Z" fill="#697E65"/><path d="M229 112V128L241 122V106ZM248 102V118L256 114V98ZM229 139V155L241 149V133ZM248 129V145L256 141V125Z" fill="#F8F5E9"/><path d="M118 83L144 70L167 82L142 96Z" fill="#94A384"/><path d="M118 83V126L142 139V96Z" fill="#A6B699"/><path d="M142 96V139L167 126V82Z" fill="#CDD6BE"/><path d="M153 36V74" stroke="#54694F" strokeWidth="3"/><path d="M154 37L180 45L154 54Z" fill="#758C6D"/><path d="M142 70V52L153 45L165 52V70" fill="#DFE6D2"/><path d="M56 153V195M286 145V184M312 169V208" stroke="#687653" strokeWidth="4"/><path d="M56 106C29 139 32 159 56 158C80 159 82 137 56 106ZM286 101C263 127 266 148 286 148C307 148 310 128 286 101ZM312 135C289 162 293 181 312 181C333 181 335 161 312 135Z" fill="#82976D"/><circle cx="78" cy="199" r="5" fill="#DAA35F"/><path d="M73 207H83L86 223H70Z" fill="#5E7059"/><path d="M74 223V232M82 223V232" stroke="#4A5946" strokeWidth="3"/><path d="M246 196L272 209L291 199" stroke="#F5F3E8" strokeWidth="3" strokeLinecap="round"/><circle cx="279" cy="42" r="3" fill="#EAE7D5"/><path d="M52 54H80M66 40V68" stroke="#A7B191" strokeWidth="1.4"/><path d="M324 100H340M332 92V108" stroke="#A7B191" strokeWidth="1.4"/></svg>;}

function Overview({t,language,requests,loading,onView,onReport,onDetail,onAsk}:{t:Labels;language:Language;requests:Grievance[];loading:boolean;onView:(v:View,id?:string|null)=>void;onReport:(c?:string)=>void;onDetail:(r:Grievance)=>void;onAsk:(q:string)=>Promise<void>}){
  const resolved=requests.filter(r=>r.status==="Resolved").length;
  return <><div className="page-heading"><div><div className="eyebrow">{t.workspace}</div><h1>{t.intro}</h1><p>{t.sub}</p></div><button className="primary-button" onClick={()=>onReport()}><Plus size={17}/>{t.new}</button></div>
    <div className="overview-top"><section className="hero-card"><div className="hero-copy"><div className="hero-eyebrow"><span/>{t.heroLabel}</div><h2>{t.heroTitle}</h2><p>{t.heroSub}</p><div className="hero-actions"><button className="dark-button" onClick={()=>onView("assistant")}><Sparkles size={17}/>{t.ask}<ArrowUpRight size={16}/></button><button className="hero-link" onClick={()=>onView("services")}>{t.explore}<ArrowRight size={15}/></button></div></div><CityIllustration/><div className="hero-bottom"><span><ShieldCheck size={13}/>Source-backed guidance</span><span>English · తెలుగు · हिन्दी</span></div></section>
    <section className="summary-card"><div className="card-title-row"><h2>Your requests</h2><span className="tiny-label">THIS WORKSPACE</span></div><div className="summary-total"><strong>{loading?"—":String(requests.length).padStart(2,"0")}</strong><span>voices heard.<br/>progress underway.</span></div><div className="summary-line"><span><i className="status-dot amber"/>{t.active}</span><strong>{loading?"—":String(requests.length-resolved).padStart(2,"0")}</strong></div><div className="summary-line"><span><i className="status-dot green"/>{t.resolved}</span><strong>{loading?"—":String(resolved).padStart(2,"0")}</strong></div><div className="summary-foot"><span className="live-dot"/>Updates saved as they happen</div></section></div>
    <section className="services-section"><div className="section-heading"><div><h2>{t.popular}</h2><p>A good place to start.</p></div><button className="text-button" onClick={()=>onView("services")}>{t.viewAll}<ArrowRight size={15}/></button></div><div className="quick-services">{[services[0],services[2],services[4],services[8],services[10]].map((s,i)=><button className={`quick-service quick-${i}`} key={s.id} onClick={()=>onView("services",s.id)}><div className="service-icon"><Icon name={s.icon} size={25}/></div><strong>{serviceTitle(s,language)}</strong><span>{s.category}<ArrowUpRight size={14}/></span></button>)}</div></section>
    <div className="overview-bottom"><section className="recent-card"><div className="section-heading"><h2>{t.recent}</h2><button className="text-button" onClick={()=>onView("requests")}>{t.seeAll}<ArrowRight size={15}/></button></div>{loading?<div className="loading-panel"><Spinner/>{t.loading}</div>:<RequestTable requests={requests.slice(0,3)} onDetail={onDetail} compact/>}<div className="sample-caption"><CircleHelp size={13}/>Your workspace starts with three labelled sample cases. New requests are saved to your session.</div></section><aside className="guidance-card"><span className="guidance-icon"><MessageCircle size={23}/><Sparkles size={12}/></span><h3>{t.help}</h3><p>{t.helpText}</p><button className="text-button" onClick={()=>void onAsk("How do I report missed waste collection?")}>{t.ask}<ArrowUpRight size={16}/></button><div className="guidance-lines" aria-hidden="true"><span/><span/><span/></div></aside></div>
  </>;
}

function Directory({t,language,search,setSearch,selectedId,onSelect,onReport,onAsk}:{t:Labels;language:Language;search:string;setSearch:(s:string)=>void;selectedId:string|null;onSelect:(id:string|null)=>void;onReport:(c:string)=>void;onAsk:(q:string)=>void}){
  const [category,setCategory]=useState("All services");const selected=services.find(s=>s.id===selectedId);
  if(selected)return <><button className="back-button" onClick={()=>onSelect(null)}><ArrowLeft size={16}/>{t.services}</button><div className="service-detail-grid"><article className="service-detail"><div className="detail-source-label"><FileText size={15}/>SAMPLE SERVICE GUIDE <span>Reviewed {shortDate(selected.reviewed)}</span></div><div className="detail-service-icon"><Icon name={selected.icon} size={32}/></div><span className="eyebrow">{selected.category}</span><h1>{serviceTitle(selected,language)}</h1><p className="detail-summary">{serviceSummary(selected,language)}</p><div className="inline-note"><ShieldCheck size={17}/><p>This is a curated sample guide for the student prototype. It does not state official fees, rules, eligibility, or processing times.</p></div><h2>How to raise a sample request</h2>{language!=="en"&&<p className="muted">Original guide in English. Ask Civic AI for guidance in your selected language.</p>}<ol className="guide-steps">{selected.steps.map((s,i)=><li key={s}><span>{i+1}</span><p>{s}</p></li>)}</ol><h2>What to include</h2><ul className="check-list">{selected.documents.map(d=><li key={d}><Check size={16}/>{d}</li>)}</ul><h2>Common questions</h2><div className="faq-list"><details><summary>Will this reach a real government department?<ChevronDown size={17}/></summary><p>No. Requests are saved in this demo app and reviewed in its staff workspace. There is no government integration.</p></details><details><summary>Are identity documents or payments required?<ChevronDown size={17}/></summary><p>No. Use synthetic information. Do not upload identity documents or pay through this prototype. Check the relevant official authority for real service requirements.</p></details><details><summary>How do I check the status?<ChevronDown size={17}/></summary><p>Use My requests in the same browser. On another browser, open Track a request and enter your reference and six-digit tracking code. Sample starter cases use code 000438.</p></details></div></article><aside className="service-detail-aside"><div className="card"><span className="eyebrow">READY TO GET STARTED?</span><h3>Let’s put it on record.</h3><p>Give us a few details and follow the progress in your workspace.</p><button className="primary-button full-width" onClick={()=>onReport(selected.category)}><Plus size={17}/>{t.new}</button><button className="secondary-button full-width" onClick={()=>onAsk(`How do I report ${selected.title.toLowerCase()}?`)}><Sparkles size={16}/>{t.ask}</button></div><div className="source-info"><FileText size={20}/><strong>About this source</strong><p>Source: CivicBridge sample knowledge base<br/>Version: 1.0<br/>Last reviewed: 30 October 2026<br/>Language: English original</p><span className="sample-pill">Clearly identified sample content</span></div></aside></div></>;
  const q=search.trim().toLowerCase();const filtered=services.filter(s=>(category==="All services"||s.category===category)&&`${s.title} ${s.te} ${s.hi} ${s.summary} ${s.keywords.join(" ")}`.toLowerCase().includes(q));
  return <><div className="page-heading"><div><div className="eyebrow">FIND THE RIGHT PLACE</div><h1>{t.services}</h1><p>Clear guidance for everyday civic needs.</p></div><span className="count-pill">15 sample services</span></div><div className="directory-search"><Search size={21}/><input aria-label="Search services" placeholder="Try “streetlight”, “water”, or “waste collection”…" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button className="icon-button" onClick={()=>setSearch("")} aria-label="Clear search"><X size={18}/></button>}</div><div className="category-tabs" role="group" aria-label="Filter by category">{["All services",...categories].map(c=><button key={c} className={c===category?"selected":""} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="results-meta"><span>{filtered.length} service{filtered.length!==1?"s":""} available</span><span><FileText size={14}/>All entries are sample guides</span></div><div className="directory-grid">{filtered.map(s=><button className="directory-card" onClick={()=>onSelect(s.id)} key={s.id}><div className="directory-card-top"><div className={`service-icon category-${categories.indexOf(s.category)}`}><Icon name={s.icon} size={25}/></div><ArrowUpRight size={18}/></div><span className="service-category">{s.category}</span><h3>{serviceTitle(s,language)}</h3><p>{serviceSummary(s,language)}</p><div className="directory-card-foot"><span><FileText size={13}/>Sample guide</span><span>Reviewed {shortDate(s.reviewed)}</span></div></button>)}</div>{!filtered.length&&<div className="empty-state"><Search size={32}/><h3>No matching services</h3><p>Try a shorter phrase or another category.</p><button className="secondary-button" onClick={()=>{setSearch("");setCategory("All services");}}>Clear filters</button></div>}</>;
}

function Assistant({t,language,messages,busy,error,onAsk,onReport,onSource,onFeedback}:{t:Labels;language:Language;messages:Message[];busy:boolean;error:string;onAsk:(q:string)=>Promise<void>;onReport:(c:string)=>void;onSource:(id:string)=>void;onFeedback:(index:number,helpful:boolean)=>Promise<void>}){
  const [draft,setDraft]=useState("");const bottom=useRef<HTMLDivElement>(null);
  useEffect(()=>{bottom.current?.scrollIntoView({behavior:"smooth",block:"nearest"});},[messages,busy]);
  const prompts=language==="te"?["చెత్త సేకరణ గురించి ఎలా ఫిర్యాదు చేయాలి?","వీధి దీపం పనిచేయడం లేదు","నీటి సరఫరా సమస్య"]:language==="hi"?["कचरा न उठने की शिकायत कैसे करें?","स्ट्रीट लाइट काम नहीं कर रही","पानी की आपूर्ति में समस्या"]:["How do I report missed waste collection?","A streetlight isn’t working. What should I do?","What do I need to report a water leak?"];
  function submit(e:FormEvent){e.preventDefault();if(draft.trim()&&!busy){void onAsk(draft);setDraft("");}}
  return <><div className="page-heading"><div><div className="eyebrow">A LITTLE HELP GOES A LONG WAY</div><h1>{t.assistant}<span className="heading-sparkle"><Sparkles size={24}/></span></h1><p>Clear answers. Visible sources. Your next step.</p></div><span className="source-backed"><ShieldCheck size={14}/>Source-backed</span></div><section className="chat-panel"><div className="chat-notice"><CircleHelp size={15}/><span>Answers use 15 sample guides. This prototype provides general guidance and cannot make official decisions.</span></div><div className="chat-messages" aria-live="polite" aria-busy={busy}>{!messages.length?<div className="chat-welcome"><div className="ai-orb"><Sparkles size={31} strokeWidth={1.5}/></div><span className="eyebrow">MEET YOUR CIVIC GUIDE</span><h2>Less searching.<br/>More moving forward.</h2><p>Tell me what’s happening. I’ll help you find<br className="desktop-break"/> the right service and explain the next steps.</p><div className="prompt-grid">{prompts.map((p,i)=><button key={p} onClick={()=>void onAsk(p)} disabled={busy}><span>{[<Trash2 size={18} key="w"/>,<Lamp size={18} key="l"/>,<Droplets size={18} key="d"/>][i]}</span>{p}<ArrowUpRight size={15}/></button>)}</div></div>:messages.map((m,index)=><div key={index} className={`message-row ${m.role}`}><div className={`message-avatar ${m.role==="assistant"?"ai-avatar":""}`}>{m.role==="assistant"?<Sparkles size={17}/>:"D"}</div><div className="message-content"><div className="message-name">{m.role==="assistant"?"Civic AI":"You"}{m.mode&&<span className={`answer-mode ${m.mode==="unsupported"?"mode-unsupported":""}`}>{m.mode==="ai-grounded"?"AI-generated · source-grounded":m.mode==="source-lookup"?"Source lookup · no generative AI":"No supported source"}</span>}</div><div className="message-text">{m.text}</div>{!!m.sources?.length&&<div className="answer-sources"><span className="source-heading"><FileText size={13}/>SOURCES USED</span>{m.sources.map(s=><a key={s.id} href={s.url} className="answer-source" onClick={e=>{e.preventDefault();onSource(s.id);}}><span className="source-file"><FileText size={17}/></span><span><strong>{s.title}</strong><small>{s.type} · Reviewed {shortDate(s.reviewed)}</small></span><ArrowUpRight size={16}/></a>)}</div>}{m.category&&<button className="answer-action" onClick={()=>onReport(m.category!)}><Plus size={15}/>Raise a sample request<ArrowRight size={14}/></button>}{m.role==="assistant"&&m.question&&<div className="feedback-row"><span>{m.feedback!==undefined?"Thanks for your feedback":"Was this helpful?"}</span><button disabled={m.feedback!==undefined} className={m.feedback===true?"feedback-selected":""} aria-label="Mark answer helpful" onClick={()=>void onFeedback(index,true)}><ThumbsUp size={14}/></button><button disabled={m.feedback!==undefined} className={m.feedback===false?"feedback-selected":""} aria-label="Mark answer not helpful" onClick={()=>void onFeedback(index,false)}><ThumbsDown size={14}/></button></div>}</div></div>)}{busy&&messages.length>0&&<div className="message-row assistant"><div className="message-avatar ai-avatar"><Sparkles size={17}/></div><div className="thinking"><span/><span/><span/><small>Checking the sample guides…</small></div></div>}{error&&<ErrorNotice>{error}</ErrorNotice>}<div ref={bottom}/></div><div className="chat-compose"><form onSubmit={submit}><input aria-label="Your question for Civic AI" placeholder={t.askPlaceholder} value={draft} maxLength={1000} onChange={e=>setDraft(e.target.value)} disabled={busy}/><button type="submit" aria-label={t.send} disabled={busy||!draft.trim()}>{busy?<Spinner/>:<ArrowRight size={21}/>}</button></form><span><ShieldCheck size={12}/>Sample guidance, with sources. Check official authorities for current requirements.</span></div></section></>;
}

function ReportForm({t,category,ready,onDone,onDetail,onNavigate}:{t:Labels;category:string;ready:boolean;onDone:()=>Promise<void>;onDetail:(r:Grievance)=>void;onNavigate:(v:View)=>void}){
  const [fields,setFields]=useState({subject:"",description:"",category,area:""}),[file,setFile]=useState<File|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState("");
  const [receipt,setReceipt]=useState<{reference:string;trackingCode:string;request:Grievance}|null>(null),[copied,setCopied]=useState(false);
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy||!ready)return;setError("");setBusy(true);try{const body=new FormData();Object.entries(fields).forEach(([k,v])=>body.append(k,v));if(file)body.append("attachment",file);const result=await api<{reference:string;trackingCode:string;request:Grievance}>("/api/grievances",{method:"POST",body});setReceipt(result);void onDone().catch(()=>{});}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  if(receipt)return <div className="receipt-wrap"><div className="receipt-card"><div className="success-orb"><CheckCheck size={34}/></div><span className="eyebrow">YOUR VOICE IS ON RECORD</span><h1>Request received.</h1><p>Your sample request is saved. Follow its journey<br className="desktop-break"/> from your workspace, whenever you need.</p><div className="receipt-info"><div><label>{t.reference}</label><strong>{receipt.reference}</strong></div><div><label>{t.trackCode}</label><strong className="tracking-code">{receipt.trackingCode}</strong></div></div><p className="receipt-hint"><ShieldCheck size={15}/>Save both details to track from another browser. The tracking code is shown here once.</p><button className="secondary-button full-width" onClick={async()=>{try{await navigator.clipboard.writeText(`CivicBridge demo request\nReference: ${receipt.reference}\nTracking code: ${receipt.trackingCode}\nTrack at ${location.origin}/track`);setCopied(true);}catch{setError("Copy is unavailable. Please note the reference and tracking code shown above.");}}}>{copied?<Check size={16}/>:<Copy size={16}/>} {copied?"Tracking details copied":"Copy tracking details"}</button><button className="primary-button full-width" onClick={()=>onDetail(receipt.request)}>View request timeline<ArrowRight size={17}/></button><button className="text-button" onClick={()=>onNavigate("requests")}>{t.requests}<ArrowRight size={15}/></button><div className="receipt-demo"><CircleHelp size={15}/>Saved to CivicBridge only. Not sent to a government department.</div>{error&&<ErrorNotice>{error}</ErrorNotice>}</div></div>;
  function sample(){const c=fields.category||"Sanitation";const topic=services.find(s=>s.category===c)!;setFields({subject:`Sample request: ${topic.title.toLowerCase()}`,description:`Synthetic demonstration: an issue with ${topic.title.toLowerCase()} needs attention near the sample community park. Please review this in the demo workflow. This is not a real-world report.`,category:c,area:"Demo Ward 04 · Sample Community Park"});}
  return <><div className="page-heading"><div><div className="eyebrow">SMALL ACTIONS. REAL POSSIBILITIES.</div><h1>{t.new}</h1><p>Tell us what needs attention in your neighbourhood.</p></div><button className="secondary-button" onClick={sample}><Sparkles size={16}/>Use sample details</button></div><div className="report-layout"><form className="report-form card" onSubmit={submit}><div className="form-section-heading"><span>01</span><div><h2>The details that matter.</h2><p>A clear description helps the right team understand the issue.</p></div></div>{error&&<ErrorNotice>{error}</ErrorNotice>}<label className="field-label">{t.subject}<span>*</span><input required minLength={5} maxLength={120} placeholder="e.g. Streetlight not working near the park" value={fields.subject} onChange={e=>setFields({...fields,subject:e.target.value})}/><small>A short, clear title. 5–120 characters.</small></label><div className="form-two-columns"><label className="field-label">{t.category}<span>*</span><select required value={fields.category} onChange={e=>setFields({...fields,category:e.target.value})}><option value="">Choose a category</option>{categories.map(c=><option key={c}>{c}</option>)}</select></label><label className="field-label">{t.area}<span>*</span><input required minLength={3} maxLength={160} placeholder="e.g. Demo Ward 04, Park Road" value={fields.area} onChange={e=>setFields({...fields,area:e.target.value})}/></label></div><label className="field-label">{t.description}<span>*</span><textarea required minLength={15} maxLength={2000} rows={6} placeholder="What happened? Where is it? When did you notice it? Use sample information only." value={fields.description} onChange={e=>setFields({...fields,description:e.target.value})}/><small className="character-count">Include what happened and a nearby public landmark.<span>{fields.description.length}/2,000</span></small></label><div className="field-label">Supporting attachment <span className="optional">Optional</span></div><label className={`upload-area ${file?"has-file":""}`}><input type="file" accept="image/png,image/jpeg,image/webp,application/pdf" aria-label="Attach a sample image or PDF" onChange={e=>{const f=e.target.files?.[0]||null;if(f&&f.size>512*1024){setError("Choose a file smaller than 512 KB.");e.target.value="";setFile(null);}else{setFile(f);setError("");}}}/><span className="upload-icon"><Paperclip size={23}/></span><strong>{file?file.name:"Click to add a sample image or document"}</strong><span>{file?`${(file.size/1024).toFixed(0)} KB · Click to replace`:"PNG, JPG, WebP or PDF · Up to 512 KB"}</span></label>{file&&<button type="button" className="text-button remove-file" onClick={()=>setFile(null)}><X size={13}/>Remove attachment</button>}<label className="consent-label"><input type="checkbox" required/><span>I’m using sample information and understand this request stays in the demo. It will not be sent to a government department.</span></label><div className="form-actions"><span><ShieldCheck size={15}/>No personal ID or payment needed</span><button className="primary-button" type="submit" disabled={busy||!ready}>{busy?<Spinner/>:<Send size={16}/>} {busy?"Saving request…":t.submit}</button></div></form><aside className="report-aside"><div className="tip-card"><div className="tip-icon"><Leaf size={22}/></div><h3>A little detail<br/>goes a long way.</h3><ul><li><CheckCircle2 size={16}/>Keep the subject specific.</li><li><CheckCircle2 size={16}/>Add a public landmark.</li><li><CheckCircle2 size={16}/>Explain what needs attention.</li><li><CheckCircle2 size={16}/>Keep personal details out.</li></ul><div className="tip-divider"/><h4>What happens next?</h4><p>You get a reference number and tracking code. Demo staff can review your request and add status updates.</p></div><div className="plain-info"><CircleHelp size={18}/><p>This is a student prototype. For real services, decisions, or immediate hazards, contact the relevant official authority directly.</p></div></aside></div></>;
}

function RequestTable({requests,onDetail,compact=false}:{requests:Grievance[];onDetail:(r:Grievance)=>void;compact?:boolean}){return <div className="table-scroll"><table className={`request-table ${compact?"compact":""}`}><thead><tr><th>REQUEST</th>{!compact&&<th>CATEGORY</th>}<th>STATUS</th><th className="table-date">UPDATED</th><th><span className="sr-only">View</span></th></tr></thead><tbody>{requests.map(r=><tr key={r.id}><td><button className="request-title-button" onClick={()=>onDetail(r)}><span className={`request-category-icon category-${categories.indexOf(r.category)}`}><Icon name={services.find(s=>s.category===r.category)?.icon||"FileText"} size={17}/></span><span><strong>{r.subject}</strong><small>{r.id}{r.is_sample&&<span className="sample-mini">Sample</span>}</small></span></button></td>{!compact&&<td className="muted">{r.category}</td>}<td><StatusBadge status={r.status}/></td><td className="table-date muted">{shortDate(r.updated_at)}</td><td><button className="icon-button table-open" aria-label={`View ${r.id}`} onClick={()=>onDetail(r)}><ChevronRight size={16}/></button></td></tr>)}</tbody></table></div>;}
function Requests({t,requests,loading,onDetail,onReport,onRefresh}:{t:Labels;requests:Grievance[];loading:boolean;onDetail:(r:Grievance)=>void;onReport:()=>void;onRefresh:()=>Promise<void>}){
  const [q,setQ]=useState(""),[filter,setFilter]=useState("All requests"),[refreshing,setRefreshing]=useState(false),[error,setError]=useState("");
  const filtered=requests.filter(r=>(filter==="All requests"||r.status===filter)&&`${r.subject} ${r.id} ${r.area}`.toLowerCase().includes(q.toLowerCase()));
  return <><div className="page-heading"><div><div className="eyebrow">EVERY REQUEST HAS A JOURNEY</div><h1>{t.requests}</h1><p>Stay in the loop, from the first report to the final update.</p></div><button className="primary-button" onClick={onReport}><Plus size={17}/>{t.new}</button></div><div className="request-stat-grid">{[{title:t.total,value:requests.length,icon:Inbox,color:"purple"},{title:"Open requests",value:requests.filter(r=>r.status!=="Resolved").length,icon:Clock3,color:"amber"},{title:t.resolved,value:requests.filter(r=>r.status==="Resolved").length,icon:CheckCheck,color:"green"}].map(s=><div className="request-stat card" key={s.title}><span className={`stat-icon ${s.color}`}><s.icon size={22}/></span><div><span>{s.title}</span><strong>{loading?"—":String(s.value).padStart(2,"0")}</strong></div><Activity size={35} className="stat-decoration"/></div>)}</div><section className="card requests-card"><div className="table-toolbar"><div className="compact-search"><Search size={17}/><input aria-label="Search your requests" placeholder="Search by subject, reference, or area…" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="table-filters"><label><Filter size={15}/><select aria-label="Filter requests by status" value={filter} onChange={e=>setFilter(e.target.value)}>{["All requests",...Object.keys(transitions)].map(s=><option key={s}>{s}</option>)}</select></label><button className="secondary-button small-button" disabled={refreshing} onClick={async()=>{setRefreshing(true);try{await onRefresh();setError("");}catch(e){setError((e as Error).message);}finally{setRefreshing(false);}}}>{refreshing?<Spinner/>:<Activity size={15}/>}Refresh</button></div></div>{error&&<ErrorNotice>{error}</ErrorNotice>}{loading?<div className="loading-panel"><Spinner/>{t.loading}</div>:filtered.length?<RequestTable requests={filtered} onDetail={onDetail}/>:<div className="empty-state"><Inbox size={32}/><h3>{t.nothing}</h3><p>Clear your search or raise a new sample request.</p></div>}<div className="table-footer"><span>{filtered.length} request{filtered.length!==1?"s":""} in this view</span><span><ShieldCheck size={13}/>Private to this browser’s demo session</span></div></section></>;
}

function Track({t,onDetail}:{t:Labels;onDetail:(r:Grievance)=>void}){
  const [reference,setReference]=useState(""),[code,setCode]=useState(""),[busy,setBusy]=useState(false),[error,setError]=useState("");
  return <div className="track-wrap"><div className="track-intro"><span className="track-orb"><Search size={31}/></span><span className="eyebrow">GOOD TO KNOW WHERE THINGS STAND</span><h1>{t.track}</h1><p>Your reference and tracking code unlock the latest updates.</p></div><form className="card track-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError("");try{onDetail(await api<Grievance>("/api/track",{method:"POST",body:JSON.stringify({reference,code})}));}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}>{error&&<ErrorNotice>{error}</ErrorNotice>}<label className="field-label">{t.reference}<input required placeholder="CBR-26-XXXXXXXXXX" value={reference} maxLength={30} onChange={e=>setReference(e.target.value.toUpperCase())}/></label><label className="field-label">{t.trackCode}<input required inputMode="numeric" pattern="[0-9]{6}" placeholder="6-digit code" value={code} maxLength={6} onChange={e=>setCode(e.target.value.replace(/\D/g,""))}/><small>You received this code when you submitted your request.</small></label><button className="primary-button full-width" disabled={busy}>{busy?<Spinner/>:<Search size={16}/>} {t.find}</button><div className="track-foot"><ShieldCheck size={15}/><p>The code keeps your request private. For your three starter sample cases, use <strong>000438</strong>.</p></div></form><p className="muted center-text">Using the same browser? Find all your cases in My requests.</p></div>;
}

function Staff({t,staff,version,onLogin,onLogout,onDetail}:{t:Labels;staff:boolean;version:number;onLogin:()=>void;onLogout:()=>void;onDetail:(r:Grievance)=>void}){
  const [password,setPassword]=useState(""),[busy,setBusy]=useState(false),[error,setError]=useState(""),[queue,setQueue]=useState<Grievance[]>([]),[filter,setFilter]=useState("All requests"),[q,setQ]=useState("");
  async function load(){setBusy(true);try{const r=await api<{requests:Grievance[]}>("/api/staff/queue");setQueue(r.requests);setError("");}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  useEffect(()=>{if(staff)void load();},[staff,version]);
  if(!staff)return <div className="track-wrap staff-login"><div className="track-intro"><span className="track-orb staff-orb"><ShieldCheck size={32}/></span><span className="eyebrow">ON THE OTHER SIDE OF EVERY REQUEST</span><h1>{t.staff}</h1><p>Review, categorise, and move sample requests forward.</p></div><form className="card track-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError("");try{await api("/api/staff/login",{method:"POST",body:JSON.stringify({password})});setPassword("");onLogin();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}>{error&&<ErrorNotice>{error}</ErrorNotice>}<label className="field-label">Staff demo password<input type="password" required autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter the provided demo password"/></label><button className="primary-button full-width" disabled={busy}>{busy?<Spinner/>:<ShieldCheck size={17}/>}Open staff workspace<ArrowRight size={16}/></button><div className="track-foot"><ShieldCheck size={15}/><p>Protected staff access. Status and category changes are recorded in each request’s history.</p></div></form></div>;
  const filtered=queue.filter(r=>(filter==="All requests"||r.status===filter)&&`${r.id} ${r.subject} ${r.category} ${r.area}`.toLowerCase().includes(q.toLowerCase()));
  return <><div className="page-heading"><div><div className="eyebrow">STAFF WORKSPACE · DEMO OPERATIONS</div><h1>A little care. Visible progress.</h1><p>Every request is a chance to make someone’s day better.</p></div><button className="secondary-button" onClick={async()=>{try{await api("/api/staff/logout",{method:"POST",body:"{}"});onLogout();}catch(e){setError((e as Error).message);}}}><LogOut size={16}/>Sign out</button></div><div className="staff-banner"><ShieldCheck size={20}/><div><strong>You’re in the staff workspace.</strong><span>All cases are demo records. Changes update citizen timelines and are saved in the audit trail.</span></div><span className="staff-badge">STAFF ACCESS</span></div><div className="request-stat-grid">{[{title:"Total in queue",value:queue.length,icon:Inbox,color:"purple"},{title:"Needs acknowledgement",value:queue.filter(r=>r.status==="Submitted").length,icon:Clock3,color:"amber"},{title:"Resolved",value:queue.filter(r=>r.status==="Resolved").length,icon:CheckCheck,color:"green"}].map(s=><div className="request-stat card" key={s.title}><span className={`stat-icon ${s.color}`}><s.icon size={22}/></span><div><span>{s.title}</span><strong>{String(s.value).padStart(2,"0")}</strong></div></div>)}</div><section className="card requests-card"><div className="table-toolbar"><div className="compact-search"><Search size={17}/><input aria-label="Search staff queue" placeholder="Search reference, subject, category, or area…" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="table-filters"><label><Filter size={15}/><select aria-label="Filter staff queue by status" value={filter} onChange={e=>setFilter(e.target.value)}>{["All requests",...Object.keys(transitions)].map(s=><option key={s}>{s}</option>)}</select></label><button className="secondary-button small-button" onClick={()=>void load()} disabled={busy}>{busy?<Spinner/>:<Activity size={15}/>}Refresh</button></div></div>{error&&<ErrorNotice>{error}</ErrorNotice>}{!busy&&filtered.length===0?<div className="empty-state"><CheckCheck size={32}/><h3>All clear in this view.</h3><p>Try another filter to see more sample requests.</p></div>:<RequestTable requests={filtered} onDetail={onDetail}/>}<div className="table-footer"><span>{filtered.length} of {queue.length} latest demo cases</span><span>Click a request to review or update it.</span></div></section></>;
}

function RequestDialog({request,staff,onClose,onUpdated}:{request:Grievance;staff:boolean;onClose:()=>void;onUpdated:()=>Promise<void>}){
  const dialog=useRef<HTMLDialogElement>(null);const [record,setRecord]=useState(request),[loading,setLoading]=useState(!request.events),[error,setError]=useState("");
  const [status,setStatus]=useState(request.status),[category,setCategory]=useState(request.category),[note,setNote]=useState(""),[busy,setBusy]=useState(false);
  useEffect(()=>{dialog.current?.showModal();if(!request.events){api<Grievance>(`/api/grievances/${request.id}`).then(r=>{setRecord(r);setStatus(r.status);setCategory(r.category);}).catch(e=>setError(e.message)).finally(()=>setLoading(false));}},[request]);
  async function save(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const r=await api<Grievance>(`/api/grievances/${record.id}`,{method:"PATCH",body:JSON.stringify({status,category,note,expectedStatus:record.status})});setRecord(r);setStatus(r.status);setCategory(r.category);setNote("");await onUpdated();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  return <dialog className="request-dialog" ref={dialog} onClose={onClose} onClick={e=>{if(e.target===e.currentTarget)dialog.current?.close();}} aria-labelledby="request-dialog-title"><div className="dialog-inner"><div className="dialog-top"><div><span className="eyebrow">{record.id}</span>{record.is_sample&&<span className="sample-pill">Sample case</span>}</div><button className="icon-button" aria-label="Close request details" onClick={()=>dialog.current?.close()}><X size={21}/></button></div><h2 id="request-dialog-title">{record.subject}</h2><div className="dialog-status-row"><StatusBadge status={record.status}/><span>{record.category}</span></div><div className="case-meta"><span><MapPin size={15}/>{record.area}</span><span><Clock3 size={15}/>Opened {shortDate(record.created_at)}</span></div><p className="case-description">{record.description}</p>{record.attachment_name&&<a className="attachment-link" href={`/api/grievances/${record.id}/attachment`}><Paperclip size={16}/>{record.attachment_name}<ArrowDownToLine size={15}/></a>}{error&&<ErrorNotice>{error}</ErrorNotice>}<div className="timeline-heading"><h3>Request journey</h3><span>All times in IST</span></div>{loading?<div className="loading-panel"><Spinner/>Loading updates…</div>:<ol className="timeline">{record.events?.map((event,i)=><li key={event.id} className={i===record.events!.length-1?"latest":""}><div className="timeline-dot">{i===record.events!.length-1?<Activity size={13}/>:<Check size={12}/>}</div><div className="timeline-content"><div><strong>{event.status}</strong><time>{longDate(event.created_at)}</time></div><p>{event.note}</p><span>{event.actor==="Demo"?"Sample workflow":event.actor}</span></div></li>)}</ol>}{staff&&<form className="staff-update-form" onSubmit={save}><div className="form-section-heading"><span><ShieldCheck size={17}/></span><div><h3>Move this request forward</h3><p>Every update appears on the citizen’s timeline.</p></div></div><div className="form-two-columns"><label className="field-label">Status<select value={status} onChange={e=>setStatus(e.target.value as Status)}><option value={record.status}>{record.status} (current)</option>{transitions[record.status].map(s=><option key={s}>{s}</option>)}</select></label><label className="field-label">Category<select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c}>{c}</option>)}</select></label></div><label className="field-label">{status==="Resolved"?"Resolution note":"Update note"}<textarea required minLength={5} maxLength={1000} rows={3} value={note} onChange={e=>setNote(e.target.value)} placeholder="Explain what changed or what happens next…"/></label><button className="primary-button full-width" disabled={busy||loading}>{busy?<Spinner/>:<CheckCheck size={17}/>}Save update</button></form>}<div className="dialog-demo-note"><CircleHelp size={14}/>This request exists in CivicBridge only. No real department has been notified.</div></div></dialog>;
}
